/// <summary>
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(tableStr(MarkupAutoLine))]
final public class METMarkupAutoLineTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Get the MarkupTable for this Line
    /// </summary>
    /// <returns>Markup table record</returns>
    public MarkupAutoTable metMarkupTable()
    {
        MarkupAutoTable metMarkupAutoTable;

        select firstonly metMarkupAutoTable
            where   metMarkupAutoTable.recId    == this.TableRecId
            &&      metMarkupAutoTable.TableId  == this.TableTableId;
        
        return metMarkupAutoTable;
    }

    /// <summary>
    /// Find method. Std method is marked as Internal
    /// </summary>
    /// <param name = "_recId">ID</param>
    /// <param name = "_forUpdate">for update</param>
    /// <returns>Markup Line record</returns>
    public static MarkupAutoLine metFindByRecId(RecId _recId, boolean _forUpdate = false)
    {
        MarkupAutoLine metMarkupAutoLine;

        if(_recId)
        {
            metMarkupAutoLine.selectForUpdate(_forUpdate);

            select firstonly metMarkupAutoLine
                where metMarkupAutoLine.recId == _recId;
        }
        return metMarkupAutoLine;
    }
